/***********************************************************/
/************** Properties: Image Responsive **************/
/*********************************************************/
img.img-w-full,
.img-w-full img {
  width: 100%;
  height: auto;
}

img.img-h-full,
.img-h-full img {
  width: auto;
  height: 100%;
}

/*************************************************/
/************** Properties: Cursor **************/
/***********************************************/
.cursor-auto {
  cursor: auto;
}

.cursor-default {
  cursor: default;
}

.cursor-pointer {
  cursor: pointer;
}

